async function database(){return new Promise((resolve,reject)=>{const req=indexedDB.open('droma-video-studio',1);req.onupgradeneeded=()=>{req.result.createObjectStore('kv');};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function dbget(key){if(!db)return;return new Promise((resolve,reject)=>{const q=db.transaction('kv').objectStore('kv').get(key);q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}
async function dbput(key,val){if(!db)throw Error('Almacenamiento local no disponible.');return new Promise((resolve,reject)=>{const tx=db.transaction('kv','readwrite');tx.objectStore('kv').put(val,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
