function sceneDraw(context,w,h,local,preset='flow'){const tm=local*.12;context.save();let grad=context.createLinearGradient(0,0,w,h);if(preset==='flow'){grad.addColorStop(0,'#142f3c');grad.addColorStop(.5,'#2b535a');grad.addColorStop(1,'#99b8a7');}else{grad.addColorStop(0,'#241f41');grad.addColorStop(.5,'#71505e');grad.addColorStop(1,'#edb385');}context.fillStyle=grad;context.fillRect(0,0,w,h);context.translate(w*.72,h*.47);context.rotate(-.32+tm*.05);for(let i=0;i<8;i++){context.beginPath();context.strokeStyle=i%2?'#b5d6c129':'#e7c6a12e';context.lineWidth=w*.025;context.ellipse(0,0,w*(.11+i*.055),h*(.22+i*.12),Math.sin(tm)*.08,0,Math.PI*2);context.stroke();}const glow=context.createRadialGradient(-w*.35,h*.3,0,-w*.35,h*.3,w*.65);glow.addColorStop(0,preset==='flow'?'#cad7ad90':'#ffb47590');glow.addColorStop(1,'#ffffff00');context.fillStyle=glow;context.fillRect(-w,-h,w*2,h*2);context.restore();}
function sceneThumb(preset){let c=thumbCanvas.getContext('2d');sceneDraw(c,240,135,0,preset);return thumbCanvas.toDataURL();}
