async function prepareAsset(a){a.inLibrary=isLibraryAsset(a);if(a.file){a.url=URL.createObjectURL(a.file);if(a.kind==='image'){const img=new Image();img.src=a.url;await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error(`No se puede abrir ${a.name}`));});a.image=img;a.width=img.naturalWidth;a.height=img.naturalHeight;try{const ct=thumbCanvas.getContext('2d');ct.clearRect(0,0,240,135);ct.drawImage(img,0,0,240,135);a.thumb=thumbCanvas.toDataURL('image/jpeg',.6);}catch{}}else{const el=document.createElement(a.kind==='audio'?'audio':'video');el.preload='auto';el.playsInline=true;el.src=a.url;await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error(`No se pudo leer ${a.name}. Comprueba su códec.`)),20000);el.onloadedmetadata=()=>{clearTimeout(timeout);resolve();};el.onerror=()=>{clearTimeout(timeout);reject(Error(`Formato o códec incompatible: ${a.name}`));};});if(!Number.isFinite(el.duration)||el.duration<=0)throw Error(`Duración no válida: ${a.name}`);a.duration=el.duration;a.width=el.videoWidth||0;a.height=el.videoHeight||0;if(a.kind==='video'){el.muted=true;try{await new Promise(resolve=>{const finish=()=>{try{thumbCanvas.getContext('2d').drawImage(el,0,0,240,135);a.thumb=thumbCanvas.toDataURL('image/jpeg',.6);}catch{}resolve();};if(el.readyState>=2){finish();return;}el.addEventListener('loadeddata',finish,{once:true});setTimeout(resolve,2500);});}catch{}}el.removeAttribute('src');el.load();}}assets.set(a.id,a);return a;}
async function importFiles(files){if(exporting)return;const list=[...files];if(!list.length)return;stop();status('Leyendo archivos…');let count=0,errors=[];for(const file of list){try{if(/\.srt$/i.test(file.name)){await importSRT(file);continue;}const type=file.type,kind=type.startsWith('image/')?'image':type.startsWith('audio/')?'audio':type.startsWith('video/')?'video':/\.(mp3|wav|ogg|flac|m4a|aac)$/i.test(file.name)?'audio':/\.(mp4|webm|mov|mkv|m4v)$/i.test(file.name)?'video':null;if(!kind)throw Error(`Archivo no admitido: ${file.name}`);const a={id:uid(),name:file.name,kind,file,duration:5};await prepareAsset(a);count++;}catch(e){errors.push(e.message);}}tab='media';renderLibrary();scheduleSave();status(`${count} archivo${count===1?'':'s'} importado${count===1?'':'s'}`);if(errors.length)toast(errors.join(' · '));}
function addAsset(id,at=t,track){if(exporting)return;const a=assets.get(id);if(!a)return;track=track||project.tracks.find(x=>x.kind===(a.kind==='audio'?'audio':'visual')&&!x.locked&&(a.kind==='audio'||x.id==='v1'))?.id||project.tracks.find(x=>x.kind===(a.kind==='audio'?'audio':'visual')&&!x.locked)?.id;if(!track){toast('Añade o desbloquea una pista compatible.');return;}const tr=project.tracks.find(x=>x.id===track);if(tr.locked||tr.kind==='audio'&&a.kind!=='audio'){toast('Utiliza una pista compatible y desbloqueada.');return;}remember();const c=makeClip(a,track,Math.max(0,at));project.clips.push(c);selected=new Set([c.id]);changed();status(`Añadido: ${a.name}`);}
