function renderLibrary(){const titles={media:'Tus medios',audio:'Biblioteca de audio',text:'Texto y gráficos',captions:'Subtítulos',effects:'Efectos y filtros',transitions:'Entrada y salida'};$('#libraryTitle').textContent=titles[tab];$('#assetCount').textContent=tab==='media'||tab==='audio'?[...assets.values()].filter(a=>isLibraryAsset(a)&&(tab==='media'||a.kind==='audio')).length:'LOCAL';$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));let html='';if(tab==='media'||tab==='audio'){html=`<button class="import-box" data-action="import">${icon('import')}<b>Importar ${tab==='audio'?'audio':'medios'}</b><small>Arrastra archivos o pulsa aquí · Ctrl I</small></button><div class="searchbox">${icon('search')}<input id="assetSearch" placeholder="Buscar en el proyecto…" aria-label="Buscar medios"></div><div class="assets" id="assetGrid"></div><p class="hint">${tab==='audio'?'MP3, WAV, OGG, M4A y FLAC si tu navegador los decodifica.':'Vídeo, audio e imagen. La compatibilidad depende del códec del archivo y del navegador.'}</p>`;}else if(tab==='text'){html=`<button class="wide-button" data-add-text="title">${icon('plus')} Añadir texto</button><p class="hint">Edita el contenido, la tipografía y el estilo en el panel derecho.</p><div class="preset-grid">${[['title','Tu historia.','Título'],['caption','Una nueva mirada','Subtítulo'],['animated','DALE AL PLAY','Título animado']].map(([id,label,name])=>`<button class="preset-card" data-add-text="${id}"><div class="preset-preview text-template" style="font-size:${id==='caption'?13:19}px;background:#252e35">${label}</div><div class="preset-name">${name}</div></button>`).join('')}<button class="preset-card" data-shape="rect"><div class="preset-preview" style="background:#252e35"><span style="display:block;background:#a2f6d0;width:70px;height:27px"></span></div><div class="preset-name">Rectángulo</div></button><button class="preset-card" data-shape="circle"><div class="preset-preview" style="background:#252e35"><span style="display:block;background:#d0c1f0;width:40px;height:40px;border-radius:50%"></span></div><div class="preset-name">Círculo</div></button></div>`;}else if(tab==='captions'){html=`<div class="project-card"><span class="eyebrow">CADA PALABRA CUENTA</span><h3>Subtítulos con<br>tu propio estilo.</h3><p>Añade frases en el cabezal o importa un archivo SRT con sus tiempos.</p></div><button class="wide-button" data-add-text="caption">${icon('plus')} Añadir subtítulo manual</button><button class="wide-button" data-action="srt-import">${icon('import')} Importar archivo SRT</button><button class="wide-button" data-action="srt-export">${icon('export')} Exportar textos como SRT</button><p class="hint">Los subtítulos son clips editables: puedes moverlos, dividirlos y darles formato.</p>`;}else if(tab==='effects'){html=`<p class="hint">Selecciona un clip visual y aplica un estilo. Los ajustes se ven y se exportan.</p><div class="preset-grid">${[['none','Original','none'],['cinema','Cine','contrast(1.2) saturate(.7)'],['warm','Cálido','sepia(.45) saturate(1.3)'],['mono','Blanco y negro','grayscale(1)'],['vintage','Vintage','sepia(.7) contrast(.8)'],['cool','Frío','hue-rotate(25deg) saturate(.7)'],['vivid','Vibrante','saturate(1.8) contrast(1.1)'],['dream','Suave','brightness(1.15) blur(1px)']].map(([id,name,filter])=>`<button class="preset-card" data-filter="${id}"><div class="preset-preview" style="filter:${filter}"><img src="logo-video-editor.svg?v=1.0.6" alt="VIVA · VIDEO EDITOR · DRÖMA" style="width:136px;height:49px;object-fit:contain"></div><div class="preset-name">${name}</div></button>`).join('')}</div><p class="hint">Más controles en Ajustes: color, croma, máscara y desenfoque.</p>`;}else{html=`<p class="hint">Aplica una entrada y una salida al clip seleccionado. Superpón clips de dos pistas para un encadenado.</p><button class="wide-button" data-action="crossfade">Crear encadenado con el clip anterior</button><div class="preset-grid">${[['none','Sin animación','↔'],['fade','Fundido','◐'],['rise','Deslizar arriba','↑'],['slide','Deslizar lateral','→'],['zoom','Acercamiento','⤢'],['wipe','Barrido','▥']].map(([id,label,symbol])=>`<button class="preset-card" data-animation="${id}"><div class="preset-preview" style="background:linear-gradient(135deg,#32454b,#1b262d)">${symbol}</div><div class="preset-name">${label}</div></button>`).join('')}</div><p class="hint">La duración de entrada y salida se ajusta en el inspector, pestaña Animación.</p>`;}$('#libraryContent').innerHTML=html;if(tab==='media'||tab==='audio')renderAssets();}
function renderAssets(query=''){const grid=$('#assetGrid');if(!grid)return;const list=[...assets.values()].filter(a=>isLibraryAsset(a)&&(tab!=='audio'||a.kind==='audio')&&a.name.toLowerCase().includes(query.toLowerCase()));grid.innerHTML=list.length?list.map(a=>`<div class="asset" draggable="true" data-asset="${a.id}" tabindex="0" title="Doble clic para añadir a la línea de tiempo · Botón derecho para eliminar de la biblioteca" aria-haspopup="menu"><div class="thumb">${assetThumb(a)?`<img src="${assetThumb(a)}" alt="" draggable="false">`:icon(a.kind==='audio'?'music':'media')}<span class="asset-time">${a.kind==='image'?'IMG':a.kind==='scene'?'DEMO':Math.floor(a.duration/60)+':'+String(Math.floor(a.duration)%60).padStart(2,'0')}</span><button class="asset-add" data-asset-add="${a.id}" title="Añadir a la línea de tiempo">${icon('plus')}</button><button class="asset-x" data-asset-remove="${a.id}" title="Eliminar clip de la biblioteca" aria-label="Eliminar clip de la biblioteca">${icon('close')}</button></div><span class="asset-name">${esc(a.name)}</span></div>`).join(''):'<div class="empty-library">Tus archivos aparecerán aquí.<br>Importa medios para empezar.</div>';}

function removeLibraryAsset(id){
 if(exporting||!removeFromLibrary(assets,id))return;
 const query=$('#assetSearch')?.value||'';
 hideEditorContextMenu();renderLibrary();
 if($('#assetSearch')){$('#assetSearch').value=query;renderAssets(query);}
 $('#assetGrid .asset')?.focus({preventScroll:true});
 dirty=true;scheduleSave();
 toast('Clip eliminado de la biblioteca. Los clips del montaje se conservan.');
}

let contextAssetId=null,contextReturnFocus=null;
function hideEditorContextMenu(returnFocus=false){
 const menu=$('#editorContextMenu');
 menu.hidden=true;contextAssetId=null;
 if(returnFocus&&contextReturnFocus?.isConnected)contextReturnFocus.focus({preventScroll:true});
 contextReturnFocus=null;
}
function openEditorContextMenu(card,x,y){
 hideEditorContextMenu();
 if(exporting||$('#modal').open||$('#manualDialog').open||!card||!isLibraryAsset(assets.get(card.dataset.asset)))return;
 const menu=$('#editorContextMenu'),rect=card.getBoundingClientRect();
 contextAssetId=card.dataset.asset;contextReturnFocus=card;
 $('#fileMenu').hidden=true;$('#projectMenu').setAttribute('aria-expanded','false');
 menu.hidden=false;
 menu.style.left=Math.max(8,Math.min(x||rect.left+12,window.innerWidth-menu.offsetWidth-8))+'px';
 menu.style.top=Math.max(8,Math.min(y||rect.bottom,window.innerHeight-menu.offsetHeight-8))+'px';
 $('#contextRemoveMedia').focus({preventScroll:true});
}
function handleContextMenuKey(e){
 if(e.key==='ContextMenu'||e.shiftKey&&e.key==='F10'){
  e.preventDefault();openEditorContextMenu(e.target.closest?.('#libraryContent .asset[data-asset]'));return true;
 }
 if($('#editorContextMenu').hidden)return false;
 if(e.key==='Escape'){e.preventDefault();hideEditorContextMenu(true);}
 else if(['ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();$('#contextRemoveMedia').focus();}
 else if(e.key==='Tab')hideEditorContextMenu(true);
 e.stopPropagation();return true;
}
document.addEventListener('contextmenu',e=>{
 e.preventDefault();
 openEditorContextMenu(e.target.closest?.('#libraryContent .asset[data-asset]'),e.clientX,e.clientY);
},{capture:true});
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#editorContextMenu'))hideEditorContextMenu();},{capture:true});
document.addEventListener('scroll',()=>hideEditorContextMenu(),{capture:true,passive:true});
window.addEventListener('resize',()=>hideEditorContextMenu());
window.addEventListener('blur',()=>hideEditorContextMenu());
$('#contextRemoveMedia').onclick=()=>{const id=contextAssetId;hideEditorContextMenu();removeLibraryAsset(id);};
const field=(label,key,value,type='number',min,max,step=1)=>`<label class="field"><span>${label}</span><input data-prop="${key}" type="${type}" value="${esc(value)}" ${min!==undefined?`min="${min}"`:''} ${max!==undefined?`max="${max}"`:''} step="${step}"></label>`;
const selectField=(label,key,value,options)=>`<label class="field"><span>${label}</span><select data-prop="${key}">${options.map(([v,l])=>`<option value="${v}" ${String(value)===String(v)?'selected':''}>${l}</option>`).join('')}</select></label>`;
const slider=(label,key,value,min=0,max=100,step=1,suffix='')=>`<div class="slider-field"><div class="slider-label"><span>${label}</span><b data-value-for="${key}">${Math.round(value*100)/100}${suffix}</b></div><input data-prop="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></div>`;
function renderInspector(){const body=$('#inspectorBody'),c=current();$('#resetClip').disabled=!c;$('#inspectorTitle').textContent=c?c.kind==='text'?'Texto':c.kind==='audio'?'Audio':'Vídeo':'Proyecto';if(!c){body.innerHTML=`<div class="project-card"><span class="eyebrow">TU ESPACIO CREATIVO</span><h3>Una historia.<br>Infinitas posibilidades.</h3><p>Selecciona un clip para darle tu forma.</p></div><section class="inspector-section"><h3>Configuración del proyecto</h3><div class="info-row"><span>Nombre</span><b>${esc(project.name)}</b></div><div class="info-row"><span>Duración</span><b>${timecode(duration(project),project.fps)}</b></div><div class="info-row"><span>Formato</span><b>${project.ratio}</b></div><label class="field"><span>Fotogramas / s</span><select id="projectFps">${[24,25,30,50,60].map(n=>`<option ${n===project.fps?'selected':''}>${n}</option>`).join('')}</select></label><label class="field"><span>Color de fondo</span><input type="color" id="projectBg" value="${project.bg}"></label></section><section class="inspector-section"><h3>Tu proyecto, contigo</h3><p class="hint">Guardado automático en este navegador. Descarga un proyecto .droma para llevarte el montaje con todos sus medios.</p><button class="wide-button" data-action="save">${icon('save')} Descargar proyecto</button><button class="wide-button" data-action="open">${icon('folder')} Abrir proyecto</button></section>`;return;}const props=animated(c,clamp(t-c.start,0,c.duration)),audio=c.kind==='audio';if(audio)inspectorTab='audio';if(!audio&&(['audio','timing'].includes(inspectorTab))&&c.kind!=='video')inspectorTab='basic';const tabs=audio?[['audio','Audio']]:[['basic','Básico'],['color','Ajustes'],['animation','Animación'],...(c.kind==='video'?[['audio','Audio']]:[])];let html=`<div class="inspector-tabs">${tabs.map(([id,label])=>`<button data-inspector-tab="${id}" class="${inspectorTab===id?'active':''}">${label}</button>`).join('')}</div><div class="info-row"><span>${esc(c.name)}</span><b>${selected.size>1?selected.size+' seleccionados':''}</b></div>`;if(isLocked(c))html+='<div class="warning">La pista está bloqueada.</div>';
if(inspectorTab==='basic'){if(c.kind==='text'){html+=`<section class="inspector-section"><h3>Contenido</h3><textarea data-prop="text" aria-label="Texto del clip">${esc(c.text)}</textarea>${selectField('Tipografía','font',c.font,[['Arial','Arial'],['Georgia','Georgia'],['Verdana','Verdana'],['Impact','Impact'],['Courier New','Courier New'],['Times New Roman','Times New Roman']])}${field('Tamaño','fontSize',c.fontSize,'number',8,400)}${selectField('Alineación','align',c.align,[['left','Izquierda'],['center','Centro'],['right','Derecha']])}${field('Color de texto','color',c.color,'color')}${field('Color de fondo','textBg',c.textBg==='transparent'?'#171b21':c.textBg,'color')}<label class="field"><span>Fondo transparente</span><input data-prop="transparentBg" type="checkbox" ${c.textBg==='transparent'?'checked':''}></label><label class="field"><span>Negrita</span><input data-prop="bold" type="checkbox" ${c.bold?'checked':''}></label><label class="field"><span>Cursiva</span><input data-prop="italic" type="checkbox" ${c.italic?'checked':''}></label><label class="field"><span>Sombra</span><input data-prop="shadow" type="checkbox" ${c.shadow?'checked':''}></label>${slider('Contorno','stroke',c.stroke||0,0,15)}${field('Color de contorno','strokeColor',c.strokeColor||'#000000','color')}</section>`;}if(c.kind==='shape')html+=`<section class="inspector-section"><h3>Forma</h3>${field('Relleno','color',c.color,'color')}${field('Anchura','shapeW',c.shapeW,'number',10,3000)}${field('Altura','shapeH',c.shapeH,'number',10,3000)}</section>`;html+=`<section class="inspector-section"><h3>Transformación <button data-action="keyframe" title="Añadir o quitar fotograma clave en el cabezal">${icon('diamond')}</button></h3>${slider('Escala','scale',props.scale,1,500,1,'%')}${field('Posición X','x',Math.round(props.x),'number',-4000,4000)}${field('Posición Y','y',Math.round(props.y),'number',-4000,4000)}${field('Rotación','rotation',Math.round(props.rotation),'number',-3600,3600)}${slider('Opacidad','opacity',props.opacity,0,100,1,'%')}${!['text','shape'].includes(c.kind)?selectField('Encuadre','fit',c.fit,[['contain','Ajustar'],['cover','Rellenar']]):''}<label class="field"><span>Voltear horizontal</span><input data-prop="flip" type="checkbox" ${c.flip?'checked':''}></label><p class="hint">${c.keyframes?.length||0} fotogramas clave. Añádelos con ◇ y cambia escala, posición, giro u opacidad.</p><div class="btn-pair"><button data-action="center">Centrar</button><button data-action="clear-keys">Borrar claves</button></div></section>`;}
if(inspectorTab==='color'){html+=`<section class="inspector-section"><h3>Color</h3>${slider('Brillo','brightness',c.brightness,0,200,1,'%')}${slider('Contraste','contrast',c.contrast,0,200,1,'%')}${slider('Saturación','saturation',c.saturation,0,250,1,'%')}${slider('Tono','hue',c.hue||0,-180,180,1,'°')}${slider('Temperatura cálida','warmth',c.warmth||0,0,100,1,'%')}${slider('Desenfoque','blur',c.blur||0,0,30,1,' px')}${selectField('Fusión','blend',c.blend||'source-over',[['source-over','Normal'],['screen','Trama'],['multiply','Multiplicar'],['overlay','Superponer'],['lighten','Aclarar'],['darken','Oscurecer']])}</section><section class="inspector-section"><h3>Máscara y recorte</h3>${selectField('Máscara','mask',c.mask||'none',[['none','Ninguna'],['circle','Círculo'],['rounded','Rectángulo redondeado']])}${slider('Recorte izquierdo','cropL',c.cropL||0,0,45,1,'%')}${slider('Recorte derecho','cropR',c.cropR||0,0,45,1,'%')}${slider('Recorte superior','cropT',c.cropT||0,0,45,1,'%')}${slider('Recorte inferior','cropB',c.cropB||0,0,45,1,'%')}</section><section class="inspector-section"><h3>Croma</h3><label class="field"><span>Eliminar color</span><input data-prop="chroma" type="checkbox" ${c.chroma?'checked':''}></label>${field('Color clave','chromaColor',c.chromaColor||'#00ff00','color')}${slider('Tolerancia','chromaTolerance',c.chromaTolerance??90,1,220)}${slider('Suavidad','chromaSoft',c.chromaSoft??35,1,100)}<p class="hint">El croma procesa cada píxel localmente. Su fluidez depende de la resolución y del equipo.</p></section>`;}
if(inspectorTab==='animation')html+=`<section class="inspector-section"><h3>Entrada y salida</h3>${selectField('Tipo','animation',c.animation,[['none','Ninguna'],['fade','Fundido'],['rise','Deslizar arriba'],['slide','Deslizar lateral'],['zoom','Acercamiento'],['wipe','Barrido']])}${slider('Entrada','fadeIn',c.fadeIn||0,0,Math.min(5,c.duration/2),.05,' s')}${slider('Salida','fadeOut',c.fadeOut||0,0,Math.min(5,c.duration/2),.05,' s')}<p class="hint">Para un encadenado, superpón el final de un clip y el inicio del siguiente en dos pistas y aplica fundidos.</p></section><section class="inspector-section"><h3>Fotogramas clave</h3><button class="wide-button" data-action="keyframe">${icon('diamond')} Marcar transformación actual</button><p class="hint">Se interpola posición, escala, giro y opacidad entre los puntos. Mueve el cabezal y cambia un valor para crear otra clave.</p></section>`;
if(inspectorTab==='audio')html+=`<section class="inspector-section"><h3>Mezcla</h3>${slider('Volumen','volume',c.volume,0,200,1,'%')}${slider('Balance','pan',c.pan||0,-100,100)}${slider('Fundido de entrada','audioIn',c.audioIn||0,0,Math.min(5,c.duration/2),.05,' s')}${slider('Fundido de salida','audioOut',c.audioOut||0,0,Math.min(5,c.duration/2),.05,' s')}${selectField('Procesamiento','audioFx',c.audioFx||'none',[['none','Sin efecto'],['telephone','Teléfono'],['presence','Presencia de voz'],['compress','Compresor']])}<label class="field"><span>Silenciar clip</span><input data-prop="audioMuted" type="checkbox" ${c.audioMuted?'checked':''}></label><p class="hint">Cambiar la velocidad conserva el tono de voz mediante el reproductor del navegador.</p>${c.kind==='video'?'<button class="wide-button" data-action="detach">Separar audio del vídeo</button>':''}</section>`;
html+=`<section class="inspector-section"><h3>Tiempo</h3>${field('Inicio (s)','start',Number(c.start.toFixed(3)),'number',0,86400,.001)}${field('Duración (s)','duration',Number(c.duration.toFixed(3)),'number',.04,86400,.001)}${['video','audio'].includes(c.kind)?selectField('Velocidad','speed',c.speed,[[.25,'0,25 ×'],[.5,'0,5 ×'],[.75,'0,75 ×'],[1,'Normal · 1 ×'],[1.25,'1,25 ×'],[1.5,'1,5 ×'],[2,'2 ×'],[3,'3 ×'],[4,'4 ×']]):''}<div class="btn-pair"><button data-action="trim-left">Recortar inicio · Q</button><button data-action="trim-right">Recortar fin · W</button></div></section>`;body.innerHTML=html;}
function setProperty(c,key,val){if(key==='speed'){c.duration=c.duration*c.speed/val;c.keyframes=(c.keyframes||[]).map(k=>({...k,t:k.t*c.speed/val}));c.speed=val;return;}if(key==='duration'){const a=assets.get(c.assetId);val=clamp(val,.04,a&&['video','audio'].includes(c.kind)?(a.duration-c.offset)/c.speed:86400);}if(key==='start')val=Math.max(0,val);if(key==='transparentBg'){c.textBg=val?'transparent':'#171b21';return;}if(['x','y','scale','rotation','opacity'].includes(key)&&c.keyframes?.length){const local=clamp(t-c.start,0,c.duration);let k=c.keyframes.find(k=>Math.abs(k.t-local)<1/project.fps);if(!k){k={t:local,...animated(c,local)};c.keyframes.push(k);}k[key]=val;}c[key]=val;}
function keyframe(){const c=current();if(!c||isLocked(c)||c.kind==='audio')return;remember();const local=clamp(t-c.start,0,c.duration),idx=c.keyframes.findIndex(k=>Math.abs(k.t-local)<1/project.fps);if(idx>=0)c.keyframes.splice(idx,1);else c.keyframes.push({t:local,...animated(c,local)});changed();}
function filters(c){const styles={none:'',cinema:'contrast(1.18) saturate(.72)',warm:'sepia(.35) saturate(1.2)',mono:'grayscale(1)',vintage:'sepia(.65) contrast(.85)',cool:'hue-rotate(22deg) saturate(.8)',vivid:'saturate(1.7) contrast(1.1)',dream:'brightness(1.12) blur(1px)'};return `brightness(${c.brightness}%) contrast(${c.contrast}%) saturate(${c.saturation}%) hue-rotate(${c.hue||0}deg) sepia(${(c.warmth||0)/100}) blur(${c.blur||0}px) ${styles[c.filter]||''}`;}
function chromaSource(source,w,h,c){scratch.width=Math.max(1,Math.min(1280,Math.round(w)));scratch.height=Math.max(1,Math.round(scratch.width*h/w));scratchCtx.clearRect(0,0,scratch.width,scratch.height);scratchCtx.drawImage(source,0,0,scratch.width,scratch.height);const im=scratchCtx.getImageData(0,0,scratch.width,scratch.height),d=im.data,col=c.chromaColor||'#00ff00',r=parseInt(col.slice(1,3),16),g=parseInt(col.slice(3,5),16),b=parseInt(col.slice(5,7),16),tol=c.chromaTolerance??90,soft=c.chromaSoft??35;for(let i=0;i<d.length;i+=4){const dist=Math.sqrt((d[i]-r)**2+(d[i+1]-g)**2+(d[i+2]-b)**2);if(dist<tol+soft)d[i+3]*=clamp((dist-tol)/soft,0,1);}scratchCtx.putImageData(im,0,0);return scratch;}
function draw(time=t,target=ctx){const w=target.canvas.width,h=target.canvas.height,s=w/1280;target.save();target.setTransform(1,0,0,1,0,0);target.globalAlpha=1;target.globalCompositeOperation='source-over';target.filter='none';target.fillStyle=project.bg;target.fillRect(0,0,w,h);const ordered=[...project.clips].filter(c=>c.kind!=='audio'&&active(c,time)&&!c.disabled&&!project.tracks.find(x=>x.id===c.track)?.hidden).sort((a,b)=>project.tracks.findIndex(x=>x.id===b.track)-project.tracks.findIndex(x=>x.id===a.track));for(const c of ordered){const local=time-c.start,p=animated(c,local),a=assets.get(c.assetId);target.save();const q=fade(c,local),anim=c.animation;let x=p.x,y=p.y,scale=p.scale/100;if(anim==='rise')y+=(1-q)*90;if(anim==='slide')x-=(1-q)*250;if(anim==='zoom')scale*=.8+.2*q;target.globalAlpha=(p.opacity/100)*q;target.globalCompositeOperation=c.blend||'source-over';target.translate(w/2+x*s,h/2+y*s);target.rotate(p.rotation*Math.PI/180);target.scale(scale*(c.flip?-1:1),scale);target.filter=filters(c);if(anim==='wipe'){target.beginPath();target.rect(-w/2,-h/2,w*q,h);target.clip();}let dw=w,dh=h;if(c.kind==='text'){const fs=(c.fontSize||80)*s;target.font=`${c.italic?'italic ':''}${c.bold?'700':'400'} ${fs}px "${c.font||'Arial'}"`;target.textAlign=c.align||'center';target.textBaseline='middle';const lines=(c.text||'').split('\n'),lh=fs*1.25,mw=Math.max(1,...lines.map(l=>target.measureText(l).width)),height=lines.length*lh;if(c.textBg&&c.textBg!=='transparent'){target.fillStyle=c.textBg;const xx=c.align==='left'?0:c.align==='right'?-mw:-mw/2;target.beginPath();target.roundRect(xx-20*s,-height/2-8*s,mw+40*s,height+16*s,6*s);target.fill();}if(c.shadow){target.shadowColor='#00000075';target.shadowBlur=10*s;target.shadowOffsetY=3*s;}target.fillStyle=c.color||'#ffffff';lines.forEach((line,i)=>{const yy=(i-(lines.length-1)/2)*lh;if(c.stroke>0){target.lineWidth=c.stroke*2*s;target.lineJoin='round';target.strokeStyle=c.strokeColor||'#000000';target.strokeText(line,0,yy);}target.fillText(line,0,yy);});}else if(c.kind==='shape'){dw=c.shapeW*s;dh=c.shapeH*s;target.fillStyle=c.color;target.beginPath();if(c.shape==='circle')target.ellipse(0,0,dw/2,dh/2,0,0,Math.PI*2);else target.roundRect(-dw/2,-dh/2,dw,dh,8*s);target.fill();}else{let source;if(c.kind==='scene'){source=null;}else if(c.kind==='image')source=a?.image;else{const p=players.get(c.id);if(p?.el.readyState>=2)source=p.el;}if(c.kind==='scene'){target.save();target.translate(-w/2,-h/2);sceneDraw(target,w,h,local*c.speed,c.preset||a?.preset);target.restore();}else if(source){const sw=source.videoWidth||source.naturalWidth||source.width,sh=source.videoHeight||source.naturalHeight||source.height;if(sw&&sh){const factor=c.fit==='cover'?Math.max(w/sw,h/sh):Math.min(w/sw,h/sh);dw=sw*factor;dh=sh*factor;target.beginPath();if(c.mask==='circle')target.ellipse(0,0,Math.min(dw,dh)/2,Math.min(dw,dh)/2,0,0,Math.PI*2);else if(c.mask==='rounded')target.roundRect(-dw/2,-dh/2,dw,dh,Math.min(dw,dh)*.15);else target.rect(-dw/2+dw*(c.cropL||0)/100,-dh/2+dh*(c.cropT||0)/100,dw*(1-((c.cropL||0)+(c.cropR||0))/100),dh*(1-((c.cropT||0)+(c.cropB||0))/100));target.clip();try{if(c.chroma)source=chromaSource(source,sw,sh,c);target.drawImage(source,-dw/2,-dh/2,dw,dh);}catch{}}}}target.restore();}target.restore();if(target===ctx){updateTime();drawGuides();}}
function visualBox(c){const w=canvas.width,h=canvas.height,s=w/1280;let rw=w,rh=h;const a=assets.get(c.assetId);if(c.kind==='text'){ctx.save();ctx.font=`${c.bold?'700':'400'} ${c.fontSize*s}px "${c.font||'Arial'}"`;rw=Math.max(30,...c.text.split('\n').map(x=>ctx.measureText(x).width))+30*s;ctx.restore();rh=c.text.split('\n').length*c.fontSize*1.25*s+12*s;}else if(c.kind==='shape'){rw=c.shapeW*s;rh=c.shapeH*s;}else if(a?.width&&a?.height){const factor=c.fit==='cover'?Math.max(w/a.width,h/a.height):Math.min(w/a.width,h/a.height);rw=a.width*factor;rh=a.height*factor;}return {w:rw,h:rh};}
function drawGuides(centerX=false,centerY=false){gctx.clearRect(0,0,guide.width,guide.height);const c=current();if(!c||c.kind==='audio'||!active(c,t)||playing||exporting)return;const p=animated(c,t-c.start),s=guide.width/1280,w=guide.width,h=guide.height,b=visualBox(c),rw=b.w*p.scale/100,rh=b.h*p.scale/100;gctx.save();gctx.translate(w/2+p.x*s,h/2+p.y*s);gctx.rotate(p.rotation*Math.PI/180);gctx.strokeStyle='#a2f6d0';gctx.lineWidth=1.5;gctx.strokeRect(-rw/2,-rh/2,rw,rh);gctx.fillStyle='#a2f6d0';for(const x of [-rw/2,rw/2])for(const y of [-rh/2,rh/2])gctx.fillRect(x-4,y-4,8,8);gctx.beginPath();gctx.moveTo(0,-rh/2);gctx.lineTo(0,-rh/2-24);gctx.stroke();gctx.beginPath();gctx.arc(0,-rh/2-28,5,0,Math.PI*2);gctx.fill();gctx.restore();if(centerX||centerY){gctx.strokeStyle='#f4bcf4';gctx.setLineDash([5,3]);gctx.beginPath();if(centerX){gctx.moveTo(w/2,0);gctx.lineTo(w/2,h);}if(centerY){gctx.moveTo(0,h/2);gctx.lineTo(w,h/2);}gctx.stroke();}}
function canvasHit(c,clientX,clientY){const rect=guide.getBoundingClientRect(),p=animated(c,t-c.start),s=canvas.width/1280,px=(clientX-rect.left)*canvas.width/rect.width-(canvas.width/2+p.x*s),py=(clientY-rect.top)*canvas.height/rect.height-(canvas.height/2+p.y*s),angle=-p.rotation*Math.PI/180,x=px*Math.cos(angle)-py*Math.sin(angle),y=px*Math.sin(angle)+py*Math.cos(angle),b=visualBox(c),rw=b.w*p.scale/100,rh=b.h*p.scale/100,near=12*canvas.width/rect.width;const corner=Math.abs(Math.abs(x)-rw/2)<near&&Math.abs(Math.abs(y)-rh/2)<near,rotate=Math.hypot(x,y+rh/2+28)<near;return {inside:Math.abs(x)<=rw/2+near&&Math.abs(y)<=rh/2+near,corner,rotate,cx:rect.left+(canvas.width/2+p.x*s)*rect.width/canvas.width,cy:rect.top+(canvas.height/2+p.y*s)*rect.height/canvas.height};}
function updateTime(){$('#currentTime').textContent=timecode(t,project.fps);$('#totalTime').textContent=timecode(duration(project),project.fps);$('#playhead').style.left=`${trackLabel()+t*zoom}px`;$('#emptyStage').hidden=project.clips.length>0;}
async function ensureAudio(){if(!audioContext){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('Este navegador no admite mezcla de audio.');audioContext=new AC();const mix=audioContext.createGain();masterGain=audioContext.createGain();analyser=audioContext.createAnalyser();analyser.fftSize=256;recordBus=audioContext.createMediaStreamDestination();mix.connect(recordBus);mix.connect(analyser);analyser.connect(masterGain);masterGain.connect(audioContext.destination);ensureAudio.mix=mix;masterGain.gain.value=muted?0:1;}if(audioContext.state==='suspended')await audioContext.resume();for(const p of players.values())connectPlayer(p);}
function connectPlayer(p){if(!audioContext||p.source)return;p.source=audioContext.createMediaElementSource(p.el);p.f1=audioContext.createBiquadFilter();p.f2=audioContext.createBiquadFilter();p.comp=audioContext.createDynamicsCompressor();p.gain=audioContext.createGain();p.pan=audioContext.createStereoPanner();p.source.connect(p.f1);p.f1.connect(p.f2);p.f2.connect(p.comp);p.comp.connect(p.gain);p.gain.connect(p.pan);p.pan.connect(ensureAudio.mix);p.el.muted=false;}
function playerFor(c){if(players.has(c.id))return players.get(c.id);const a=assets.get(c.assetId);if(!a?.url)return null;const el=document.createElement(c.kind==='audio'?'audio':'video');el.src=a.url;el.preload='auto';el.playsInline=true;el.muted=true;el.preservesPitch=true;el.addEventListener('seeked',()=>{if(!playing)draw();});el.addEventListener('loadeddata',()=>{if(!playing)draw();});el.addEventListener('error',()=>status(`No se puede reproducir: ${c.name}`));const p={el};players.set(c.id,p);connectPlayer(p);return p;}
function syncPlayers(){const ids=new Set(project.clips.map(c=>c.id));for(const [id,p] of players)if(!ids.has(id)){p.el.pause();p.source?.disconnect();p.pan?.disconnect();p.el.removeAttribute('src');p.el.load();players.delete(id);}for(const c of project.clips){if(!['video','audio'].includes(c.kind))continue;const p=playerFor(c);if(!p)continue;const a=assets.get(c.assetId),tr=project.tracks.find(x=>x.id===c.track),on=active(c,t)&&!c.disabled&&!tr?.hidden;let local=clamp(t-c.start,0,c.duration),desired=clamp(c.offset+local*c.speed,0,Math.max(0,(a?.duration||0)-.001));if((on||t<c.start)&&p.el.readyState>=1){p.el.playbackRate=c.speed;if(Math.abs(p.el.currentTime-desired)>(playing?.08:.008)){try{p.el.currentTime=desired;}catch{}}}if(p.gain){let vol=on&&!c.audioMuted&&!tr?.muted?c.volume/100*fade(c,local,true):0;p.gain.gain.setTargetAtTime(vol,audioContext.currentTime,.008);p.pan.pan.value=clamp((c.pan||0)/100,-1,1);const fx=c.audioFx||'none';p.f1.type=fx==='telephone'?'highpass':'peaking';p.f1.frequency.value=fx==='telephone'?400:2200;p.f1.gain.value=fx==='presence'?4:0;p.f1.Q.value=.7;p.f2.type='lowpass';p.f2.frequency.value=fx==='telephone'?3400:Math.min(22000,audioContext.sampleRate/2);p.comp.threshold.value=fx==='compress'?-24:0;p.comp.ratio.value=fx==='compress'?4:1;p.comp.knee.value=12;}if(on&&playing){if(p.el.paused)p.el.play().catch(()=>status('El navegador no ha podido iniciar un medio. Comprueba el códec.'));}else if(!p.el.paused)p.el.pause();}}
