 if(layout.compact){
  const label=layout.tiny?'':`${icon(indicators.length===1?indicators[0].icon:'sparkles')}<span>${indicators.length}</span>`;
  return `<div class="clip-badges compact ${layout.tiny?'tiny':''}">${summary(label,layout.tiny?'dot':'')}</div>`;
 }
 const badges=layout.visible.map(item=>`<button type="button" class="clip-badge badge-${item.id}" data-clip-adjust="${item.id}" data-mod-clip="${clip.id}" title="${esc(item.title+': '+item.details)}" aria-label="Abrir ${esc(item.title)}: ${esc(item.details)}">${icon(item.icon)}<span>${esc(item.label)}</span></button>`).join('');
