let waveformQueue=Promise.resolve();
function buildWave(asset,retry=false){
 if(!asset||!['video','audio'].includes(asset.kind))return;
 if(asset.waveform||['queued','decoding'].includes(asset.waveStatus))return;
 if(asset.waveStatus==='unavailable'&&!retry)return;
 if(!asset.file){asset.waveStatus='unavailable';asset.waveError='No se encuentra el archivo original.';return;}
 asset.waveStatus='queued';asset.waveError='';
 waveformQueue=waveformQueue.catch(()=>{}).then(async()=>{
  if(assets.get(asset.id)!==asset)return;
  asset.waveStatus='decoding';drawWaves();
  try{
   const Offline=window.OfflineAudioContext||window.webkitOfflineAudioContext;
   if(!Offline)throw Error('El navegador no permite analizar este audio.');
   // Analyse the audible source bandwidth locally; playback and exports retain the original file.
   const offline=new Offline(1,1,48000);
   const buffer=await offline.decodeAudioData(await asset.file.arrayBuffer());
   if(assets.get(asset.id)!==asset)return;
   const channels=Array.from({length:buffer.numberOfChannels},(_,channel)=>buffer.getChannelData(channel));
   const waveform=await buildPeakEnvelope(channels,buffer.sampleRate,{isCancelled:()=>assets.get(asset.id)!==asset});
   if(assets.get(asset.id)!==asset)return;
   asset.waveform=waveform;
   asset.waveStatus=waveform.maxAbs>1e-7?'ready':'silent';
  }catch(error){
   if(assets.get(asset.id)!==asset||error.name==='AbortError')return;
   asset.waveStatus='unavailable';
   asset.waveError='Sin pista de audio o códec de audio no analizable por este navegador.';
  }
  if(assets.get(asset.id)===asset)drawWaves();
 });
}
function drawWaves(){
 $$('[data-wave]').forEach(can=>{
  const clip=project.clips.find(c=>c.id===can.dataset.wave),asset=clip&&assets.get(clip.assetId);
  if(!clip||!asset)return;
  buildWave(asset);
  const band=can.closest('[data-wave-band]'),label=band.querySelector('[data-wave-status]'),retry=band.querySelector('[data-wave-retry]');
  const state=asset.waveStatus||'queued',track=project.tracks.find(tr=>tr.id===clip.track);
  band.dataset.state=state;
  band.classList.toggle('audio-muted',!!(clip.audioMuted||clip.volume===0||track?.muted||track?.hidden));
  const states={queued:'Audio en espera…',decoding:'Analizando audio…',silent:'Sin sonido audible',unavailable:'Audio no analizable'};
  label.textContent=states[state]||'';
  band.title=state==='unavailable'?asset.waveError:'Forma de onda del audio original';
  retry.hidden=state!=='unavailable';
  can.setAttribute('aria-label',states[state]||`Forma de onda del audio de ${clip.name}`);
  const cssWidth=Math.max(1,can.clientWidth||clip.duration*zoom),dpr=Math.min(2,window.devicePixelRatio||1);
  const width=Math.max(1,Math.min(4096,Math.ceil(cssWidth*dpr))),height=Math.max(1,Math.round((can.clientHeight||22)*dpr));
  if(can.width!==width)can.width=width;
  if(can.height!==height)can.height=height;
  const context=can.getContext('2d');context.clearRect(0,0,width,height);
  if(!asset.waveform)return;
  const mid=height/2,amplitude=height*.43;
  context.strokeStyle=clip.kind==='video'?'#95e3ef':'#8ad2bc';context.lineWidth=1;
  context.beginPath();context.moveTo(0,mid+.5);context.lineTo(width,mid+.5);context.globalAlpha=.24;context.stroke();context.globalAlpha=1;
  context.fillStyle=clip.kind==='video'?'#95e3ef':'#8ad2bc';
  for(let column=0;column<width;column++){
   const peak=clipColumnPeaks(asset.waveform,clip,column,width);
   if(peak.min===0&&peak.max===0)continue;
   const top=mid-Math.min(1,peak.max)*amplitude,bottom=mid-Math.max(-1,peak.min)*amplitude;
   context.fillRect(column,top,1,Math.max(1,bottom-top));
  }
 });
}
function selectClip(id,multi=false){if(!multi)selected.clear();if(multi&&selected.has(id))selected.delete(id);else selected.add(id);renderTimeline();renderInspector();draw();}
function split(all=false){if(exporting)return;const ids=all?project.clips.map(c=>c.id):[...selected];if(!project.clips.some(c=>ids.includes(c.id)&&t>c.start+.02&&t<end(c)-.02&&!isLocked(c)))return toast('Coloca el cabezal dentro de un clip seleccionado.');remember();const result=splitClips(project,ids,t);selected=new Set(result);changed();}
function removeSelected(){if(exporting)return;const list=editable();if(!list.length)return;remember();const ids=new Set(list.map(c=>c.id));if(ripple){for(const tr of project.tracks){const deleted=list.filter(c=>c.track===tr.id).sort((a,b)=>a.start-b.start);for(const c of project.clips.filter(c=>c.track===tr.id&&!ids.has(c.id))){const removed=deleted.filter(d=>end(d)<=c.start).reduce((sum,d)=>sum+d.duration,0);c.start=Math.max(0,c.start-removed);}}}project.clips=project.clips.filter(c=>!ids.has(c.id));selected.clear();changed();}
