function paste(){if(exporting||!clipboard.length)return;remember();const first=Math.min(...clipboard.map(c=>c.start));let ids=[];for(const c of clone(clipboard)){if(!project.tracks.some(tr=>tr.id===c.track&&!tr.locked))continue;c.id=uid();c.start=t+c.start-first;project.clips.push(c);ids.push(c.id);}selected=new Set(ids);changed();}
