function demoAudio(){const sr=22050,secs=12,n=sr*secs,buffer=new ArrayBuffer(44+n*2),v=new DataView(buffer);const str=(o,s)=>[...s].forEach((c,i)=>v.setUint8(o+i,c.charCodeAt(0)));str(0,'RIFF');v.setUint32(4,36+n*2,true);str(8,'WAVE');str(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,sr,true);v.setUint32(28,sr*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,n*2,true);const notes=[130.81,164.81,196,261.63,164.81,196,246.94,293.66];for(let i=0;i<n;i++){const x=i/sr,note=notes[Math.floor(x*2)%notes.length],phase=x%.5,env=Math.exp(-phase*6)*Math.min(1,x/1.2,(secs-x)/1.2);const sample=(Math.sin(2*Math.PI*note*x)*.06+Math.sin(2*Math.PI*note*2*x)*.015)*env;v.setInt16(44+i*2,sample*32767,true);}return new File([buffer],'Atmósfera Dröma.wav',{type:'audio/wav'});}
