function availableFormats(){if(!window.MediaRecorder||!canvas.captureStream)return [];return [['video/mp4;codecs=avc1.42E01E,mp4a.40.2','MP4 · H.264 / AAC','mp4'],['video/mp4','MP4 · codificador del navegador','mp4'],['video/webm;codecs=vp9,opus','WebM · VP9 / Opus','webm'],['video/webm;codecs=vp8,opus','WebM · VP8 / Opus','webm'],['video/webm','WebM · codificador del navegador','webm']].filter(([m])=>MediaRecorder.isTypeSupported(m)).filter((f,i,arr)=>arr.findIndex(x=>x[2]===f[2])===i);}
function exportModal(){if(exporting)return;if(!duration(project))return toast('El proyecto está vacío.');stop();const formats=availableFormats();if(!formats.length){modal('Exportación no compatible','<p>Este navegador no ofrece un codificador de vídeo compatible. Abre el editor en una versión actual de Chrome o Edge y vuelve a intentarlo.</p>','<button class="primary" data-close>Cerrar</button>');return;}modal('Exportar tu historia',`<div class="export-cover"><span>DRÖMA VIDEO EDITOR</span><strong>${esc(project.name)}</strong></div><label class="field"><span>Nombre</span><input id="exportName" type="text" value="${esc(project.name)}"></label><label class="field"><span>Formato</span><select id="exportFormat">${formats.map(([mime,name,ext])=>`<option value="${mime}" data-ext="${ext}">${name}</option>`).join('')}</select></label><label class="field"><span>Resolución</span><select id="exportResolution"><option value="720">720p</option><option value="1080" selected>1080p</option><option value="2160">2160p · 4K</option></select></label><label class="field"><span>Fotogramas por segundo</span><select id="exportFps">${[24,25,30,50,60].map(n=>`<option ${n===project.fps?'selected':''}>${n}</option>`).join('')}</select></label><label class="field"><span>Calidad</span><select id="exportQuality"><option value="6">Estándar · 6 Mbps</option><option value="12" selected>Alta · 12 Mbps</option><option value="25">Muy alta · 25 Mbps</option><option value="45">4K · 45 Mbps</option></select></label><div class="info-row"><span>Duración</span><b>${timecode(duration(project),project.fps)}</b></div><div class="checks">Se exporta la composición completa con audio, textos, croma, efectos y animación. Sin marca de agua.</div><p class="hint" style="margin-top:12px">La exportación web graba en tiempo real. Mantén esta pestaña visible hasta terminar. Su calidad y fluidez dependen del equipo. Los formatos disponibles los determina el navegador.</p>`,`<button class="secondary" data-close>Cancelar</button><button class="primary" id="startExport">${icon('export')} Exportar vídeo</button>`);$('#startExport').onclick=startExport;}
async function waitMediaReady(){syncPlayers();const activePlayers=project.clips.filter(c=>active(c,t)&&['video','audio'].includes(c.kind)).map(c=>players.get(c.id)).filter(Boolean);await Promise.all(activePlayers.map(p=>new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{cleanup();reject(Error('Un medio no está listo para exportar. Espera a que termine de cargarse.'));},15000);const check=()=>{if(p.el.readyState>=2&&!p.el.seeking){cleanup();resolve();}};const cleanup=()=>{clearTimeout(timeout);p.el.removeEventListener('loadeddata',check);p.el.removeEventListener('seeked',check);};p.el.addEventListener('loadeddata',check);p.el.addEventListener('seeked',check);check();})));}
async function startExport(){if(exporting)return;const mime=$('#exportFormat').value,ext=$('#exportFormat').selectedOptions[0].dataset.ext,res=+$('#exportResolution').value,fps=+$('#exportFps').value,quality=+$('#exportQuality').value,name=safeName($('#exportName').value),oldT=t;let recorder,stream,exportCanvas,raf,recover,wasCancelled=false,failed=false;try{await ensureAudio();const [rw,rh]=project.ratio.split(':').map(Number);exportCanvas=document.createElement('canvas');exportCanvas.width=rw>=rh?Math.round(res*rw/rh/2)*2:res;exportCanvas.height=rw>=rh?res:Math.round(res*rh/rw/2)*2;const ex=exportCanvas.getContext('2d',{alpha:false});t=0;await waitMediaReady();draw(0,ex);stream=exportCanvas.captureStream(fps);const audioTracks=recordBus.stream.getAudioTracks();audioTracks.forEach(tr=>stream.addTrack(tr.clone()));recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:quality*1000000,audioBitsPerSecond:192000});const chunks=[];exporting=true;wasCancelled=false;modal('Exportando vídeo',`<div class="export-cover"><span>RENDERIZANDO TU HISTORIA</span><strong id="exportPercent">0 %</strong></div><div class="progress"><i id="exportProgress"></i></div><p id="exportStatus">Preparando los medios…</p><p class="hint">Mantén visible esta pestaña. El vídeo se descargará al terminar.</p>`,`<button class="secondary" id="cancelExport">Cancelar exportación</button>`);$('#cancelExport').onclick=()=>{wasCancelled=true;finish();};recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};let wakeLock;try{wakeLock=await navigator.wakeLock?.request('screen');}catch{}recover=()=>{cancelAnimationFrame(loopId);playing=false;exporting=false;exportTick=null;cancelAnimationFrame(raf);for(const p of players.values())p.el.pause();stream?.getTracks().forEach(tr=>tr.stop());wakeLock?.release().catch(()=>{});document.removeEventListener('visibilitychange',visibility);t=oldT;syncPlayers();draw();$('#play').innerHTML=icon('play');};const finish=()=>{if(recorder.state!=='inactive')recorder.stop();};const visibility=()=>{if(document.hidden){wasCancelled=true;failed=true;finish();}};document.addEventListener('visibilitychange',visibility);recorder.onerror=e=>{failed=true;wasCancelled=true;finish();toast(e.error?.message||'Ha fallado la exportación.');};recorder.onstop=()=>{recover();if(wasCancelled){modal('Exportación detenida',`<p>${failed?'La pestaña ha perdido visibilidad o el codificador ha fallado. Vuelve a exportar con la pestaña visible y, si hace falta, reduce la resolución.':'Se ha cancelado la exportación. Tu proyecto sigue disponible.'}</p>`,'<button class="primary" data-close>Volver al editor</button>');return;}const blob=new Blob(chunks,{type:recorder.mimeType||mime});if(!blob.size){toast('El navegador no ha generado datos de vídeo.');closeModal();return;}download(blob,`${name}.${ext}`);modal('Vídeo exportado',`<div class="export-cover"><span>LISTO PARA COMPARTIR</span><strong>${esc(name)}.${ext}</strong></div><p>${(blob.size/1024/1024).toFixed(1)} MB · ${exportCanvas.width} × ${exportCanvas.height} · ${fps} fps</p><button class="wide-button" id="downloadAgain">${icon('export')} Descargar de nuevo</button>`,'<button class="primary" data-close>Volver a editar</button>');$('#downloadAgain').onclick=()=>download(blob,`${name}.${ext}`);status('Vídeo exportado');};playing=true;lastFrame=performance.now();syncPlayers();recorder.start(1000);exportTick=(done=false)=>{const pct=Math.min(100,t/duration(project)*100);$('#exportProgress').style.width=pct+'%';$('#exportPercent').textContent=Math.floor(pct)+' %';$('#exportStatus').textContent=`${timecode(t,project.fps)} / ${timecode(duration(project),project.fps)}`;draw(t,ex);if(done)finish();};loopId=requestAnimationFrame(tick);}catch(e){recover?.();exporting=false;playing=false;stream?.getTracks().forEach(tr=>tr.stop());t=oldT;syncPlayers();draw();toast('No se pudo exportar: '+e.message);}}
function crossfade(){const c=current();if(!c||c.kind==='audio'||isLocked(c))return toast('Selecciona el segundo clip visual.');const prev=project.clips.filter(x=>x.kind!=='audio'&&x.id!==c.id&&x.start<c.start&&end(x)<=c.start+.1).sort((a,b)=>end(b)-end(a))[0];if(!prev)return toast('No se encuentra un clip visual anterior.');remember();let track=project.tracks.filter(x=>x.kind==='visual'&&!x.locked).find(x=>project.tracks.indexOf(x)<project.tracks.findIndex(y=>y.id===prev.track)&&!project.clips.some(z=>z.track===x.id&&z.id!==c.id&&z.start<end(prev)+c.duration&&end(z)>end(prev)-.5));if(!track){track={id:uid(),name:'Encadenado',kind:'visual'};project.tracks.unshift(track);}const overlap=Math.min(.5,c.duration/2,prev.duration/2);c.start=end(prev)-overlap;c.track=track.id;c.fadeIn=overlap;c.animation='fade';changed();toast('Encadenado creado en dos pistas.');}
