document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close'))return closeModal();if(exporting)return;if(b.dataset.clipAdjust){openClipAdjustment(b.dataset.modClip,b.dataset.clipAdjust);return;}if(b.dataset.action){$('#fileMenu').hidden=true;actions[b.dataset.action]?.();}if(b.dataset.waveRetry){const asset=assets.get(b.dataset.waveRetry);if(asset){buildWave(asset,true);drawWaves();}}if(b.dataset.tab){tab=b.dataset.tab;renderLibrary();}if(b.dataset.inspectorTab){inspectorTab=b.dataset.inspectorTab;renderInspector();}if(b.dataset.addText)addText(b.dataset.addText);if(b.dataset.shape)addShape(b.dataset.shape);if(b.dataset.assetAdd)addAsset(b.dataset.assetAdd);if(b.dataset.assetRemove)removeLibraryAsset(b.dataset.assetRemove);if(b.dataset.filter){const cs=editable().filter(c=>c.kind!=='audio');if(!cs.length)return toast('Selecciona un clip visual para aplicar el filtro.');remember();cs.forEach(c=>c.filter=b.dataset.filter);changed();}if(b.dataset.animation){const cs=editable().filter(c=>c.kind!=='audio');if(!cs.length)return toast('Selecciona un clip visual.');remember();cs.forEach(c=>{c.animation=b.dataset.animation;c.fadeIn=c.animation==='none'?0:Math.min(.5,c.duration/2);c.fadeOut=c.animation==='none'?0:Math.min(.5,c.duration/2);});inspectorTab='animation';changed();}if(b.dataset.trackAction){const tr=project.tracks.find(tr=>tr.id===b.dataset.id);remember();const key={hide:'hidden',mute:'muted',lock:'locked'}[b.dataset.trackAction];tr[key]=!tr[key];changed();}if(b.dataset.marker){const m=project.markers.find(m=>m.id===b.dataset.marker);seek(m.time);}});
